def f(g):
    H,W=len(g),len(g[0])
    rows_with=[i for i,r in enumerate(g) if any(c for c in r)]
    sr=rows_with[0]
    st=[c for c in g[sr] if c]
    seq=list(set(st))
    # object: nonzero cells below stripe
    cells=[]
    for r in range(sr+1,H):
        for c,v in enumerate(g[r]):
            if v: cells.append((r-sr-1,c-v))
    # anchor color = color of cells in object (demo1: mixed; demo2: mixed 2&1)
    ocols={v for _,_,v in [(r-c[0],c[1],g[r][c[0]]) for r,c in []]} 
    ocols=set()
    for r in range(sr+1,H):
        for c,v in enumerate(g[r]):
            if v: ocols.add(v)
    missing=[c for c in seq if c not in ocols]
    # order: missing before-anchor, after-anchor by position in seq
    anc_idx=[seq.index(c) for c in ocols]
    b_before=[c for c in missing if seq.index(c)<min(anc_idx)] if anc_idx else []
    b_after=[c for c in missing if seq.index(c)>max(anc_idx)] if anc_idx else []
    tops=sorted(ocols,key=lambda c:min(r for rr,cc,v in cells if v==c))
    # anchor top row
    atr=min(r for rr,cc,v in cells if v in ocols & {tops[0]}) if tops else sr+1
    atops=sorted([min(r for rr,cc,v in cells if v==c) for c in tops])
    atop=atops[0] if atops else atr
    out=[[0]*W for _ in range(H)]
    for r in range(sr+1,H):
        for c,v in enumerate(g[r]):
            if v: out[r][c]=v
    n=missing[:]
    # bands placed adjacent to object, extending outward away from stripe
    # determine side: object below stripe; extend down for after, up for before
    def place(c,before):
        h=max(rr for rr,cc,v in cells)+1-atop  # object height
        s=top if before else atop+h
        for rr,cc,v in cells:
            out[s+rr-atop][cc]=c
    before=missing[:len(missing)//2] if False else [m for m in missing if m in seq[:min([s.index(c) for c in tops])] ]
    # simpler: colors before anchor in seq go above, after go below
    anc=sorted(tops)
    before=[m for m in missing if seq.index(m)<seq.index(anc[0])]
    after=[m for m in missing if seq.index(m)>seq.index(anc[-1])]
    def put(m,before):
        h=max(rr for rr,cc,v in cells)+1-atop
        s=(atop-h) if before else (atop+h)
        for rr,cc,v in cells:
            r=s+rr
            if 0<=r<H: out[r][cc]=m
    for m in before: put(m,True)
    for m in after: put(m,False)
    return out
