def solve(gi):
    Hh,Ww=len(gi),len(gi[0])
    cnt=Counter(v for r_ in gi for v in r_)
    bg=0 if 0 in cnt else None
    best=None
    for c in cnt:
        if c==bg: continue
        for cs in comps_of(gi,c):
            if best is None or len(cs)>len(best[1]): best=(c,set(cs))
    tc_,ts=best
    t0=min(y for y,_ in ts); t1=max(y for y,_ in ts)
    c0=min(x for _,x in ts); c1=max(x for _,x in ts)
    bh=t1-t0+1; bw=c1-c0+1
    rel={(y-t0,x-c0) for y,x in ts}
    bars=[]
    for c in cnt:
        if c==tc_: continue
        for cs in comps_of(gi,c):
            s=set(cs)
            ys={y for y,_ in s}; xs={x for _,x in s}
            if len(xs)!=1 or len(s)<2: continue
            top=min(ys); x0=list(xs)[0]
            if x0<c0 or x0>c1: continue
            bars.append((top,x0,c))
    out=[r[:] for r in gi]
    # clear original bars (cells of their color at their column, contiguous vertical run >=2)
    for top,x0,col in bars:
        cells=[(y,x0) for y in range(Hh) if gi[y][x0]==col and abs(y-top)<=bh]
        for y,x in cells: out[y][x]=0
    A=[b for b in bars if b[1]<c0]; B=[b for b in bars if b[1]>c1]
    for k,b in enumerate(A+B):
        row = t0-bh-(k*bh) if b[0]<c0 else t1+bh+k*bh
        for fy,fx in rel:
            yy=row+fy; xx=b[1]+fx
            if 0<=yy<Hh and 0<=xx<Ww: out[yy][xx]=b[2]
    return out
