    ts,tcol=best
    tset=set(ts); t0=min(y for y,_ in ts); t1=max(y for y,_ in ts)
    c0=min(x for _,x in ts); c1=max(x for _,x in ts)
    rel={(y-t0,x-c0) for y,x in ts}
    # bars: vertical 1-wide components, height>=2, not overlapping template
    bars=[]; anchors=[]
    seen=set()
    for c in Counter(flat):
        if c in (bg,tcol): continue
        for cs in comps_of(gi,c):
            s=set(cs)
            if s & seen or s & tset: continue
            ys={y for y,_ in s}; xs={x for _,x in s}
            if len(xs)==1 and len(ys)>=2:
                bars.append((min(ys),max(ys),c,s)); seen|=s
            else:
                anchors.append(s); seen|=s
    out=[row[:] for row in gi]
    def band(rr,col):
        for dy,dx in rel:
            yy=rr+dy; xx=c0+dx
            if 0<=yy<H and 0<=xx<W: out[yy][xx]=col
    for bar in bars:
        rr,rb,col,cells=bar
        # slide down until next step would overlap an anchor or band
        cur=range(rr,rr+3)
        while True:
            nxt=list(cur)[0]+1  # placeholder
            ncur=[r+1 for r in cur]
            if ncur[-1]>=H-1: break
            # does moving down by 1 hit an anchor?
            hit=False
            for ay in anchors:
                if any(r in (ncur[0],ncur[1],ncur[2]) for r,_ in [(y,x) for y,x in ay] if False) or False: pass
            # simpler: check cells directly below band bottom
            if any((nr,c0+i) in set().union(*anchors) for nr in (ncur[2]+1,) for i in range(c1-c0+1)): hit=True
            # actually check overlap with anchors precisely
            below={(nr,x) for nr in (ncur[2]+1,) for x in range(c0,c1+1)}
